'use strict';
const $=id=>document.getElementById(id),H=Horar,KEY='horar.journal.v1';let current=null,currentId=null;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cities={moscow:[55.7558,37.6173,'Europe/Moscow'],petersburg:[59.9343,30.3351,'Europe/Moscow'],ryazan:[54.6296,39.7419,'Europe/Moscow'],kanash:[55.5096,47.4913,'Europe/Moscow'],kazan:[55.7961,49.1064,'Europe/Moscow'],ekaterinburg:[56.8389,60.6057,'Asia/Yekaterinburg'],novosibirsk:[55.0084,82.9357,'Asia/Novosibirsk'],berlin:[52.52,13.405,'Europe/Berlin'],london:[51.5074,-.1278,'Europe/London']};
function notify(id,text){$(id).textContent=text;}
function readEntries(){try{const a=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(a)?a:[];}catch{return [];}}
function writeEntries(entries){try{localStorage.setItem(KEY,JSON.stringify(entries));$('count').textContent=entries.length;return true;}catch{notify('status','Не удалось сохранить: память устройства недоступна или заполнена. Экспортируйте карту.');notify('journal-status','Не удалось сохранить данные. Экспортируйте журнал.');return false;}}
function page(id){document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===id));if(id==='journal')renderJournal();window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>page(b.dataset.page));document.querySelector('.brand').onclick=e=>{e.preventDefault();page('workspace');};
function cityOffset(){const city=cities[$('city').value];if(!city)return;const d=new Date($('moment').value+'Z');if(!Number.isFinite(+d))return;try{let parts=new Intl.DateTimeFormat('en-GB',{timeZone:city[2],timeZoneName:'longOffset'}).formatToParts(d),v=parts.find(p=>p.type==='timeZoneName').value,m=v.match(/GMT([+-])(\d{2}):(\d{2})/);$('offset').value=m?(m[1]==='-'?-1:1)*(+m[2]+m[3]/60):0;}catch{} }
function now(){const city=cities[$('city').value];const zone=city?city[2]:null;let d=new Date();if(zone){const f=new Intl.DateTimeFormat('sv-SE',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);$('moment').value=f.replace(' ','T');cityOffset();}else $('moment').value=new Date(+d+Number($('offset').value)*3600000).toISOString().slice(0,16);}
$('now').onclick=now;$('city').onchange=()=>{const c=cities[$('city').value];if(c){$('lat').value=c[0];$('lon').value=c[1];cityOffset();}};$('moment').onchange=cityOffset;for(const id of ['lat','lon'])$(id).oninput=()=>{$('city').value='custom';};
function input(){return {question:$('question').value,utc:new Date(new Date($('moment').value+'Z').getTime()-Number($('offset').value)*3600000).toISOString(),local:$('moment').value,offset:Number($('offset').value),city:$('city').value,lat:Number($('lat').value),lon:Number($('lon').value),system:$('system').value,target:Number($('target').value)};}
function formatLon(l){const total=Math.round(H.mod(l)*60)%21600,s=Math.floor(total/1800),d=Math.floor(total%1800/60),m=total%60;return `${d}°${String(m).padStart(2,'0')}′ ${H.signs[s]}`;}
function localTime(utc,offset){return new Date(+new Date(utc)+offset*3600000).toISOString().slice(0,16).replace('T',' ')+` UTC${offset>=0?'+':''}${offset}`;}
const glyphSigns=['♈','♉','♊','♋','♌','♍','♎','♏','♐','♑','♒','♓'];
function wheel(c){let out='',asc=c?c.asc:0;const pt=(l,r)=>{const a=(180+asc-l)*Math.PI/180;return [320+r*Math.cos(a),320+r*Math.sin(a)];};const line=(a,b,col,width=1,extra='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${col}" stroke-width="${width}" ${extra}/>`;const text=(l,r,s,size=18,color='#78847c')=>{let p=pt(l,r);return `<text x="${p[0]}" y="${p[1]}" text-anchor="middle" dominant-baseline="middle" fill="${color}" font-family="Georgia,serif" font-size="${size}">${s}</text>`;};
 for(const r of [290,282,246,229,182,172])out+=`<circle cx="320" cy="320" r="${r}" fill="none" stroke="${r===282?'#b69b71':'#d9ddd1'}" stroke-width="${r===282?1.3:.8}"/>`;
 for(let l=0;l<360;l++)out+=line(pt(l,282),pt(l,l%30===0?268:l%5===0?275:279),'#b3b9ac',l%30===0?1:.5);
 for(let s=0;s<12;s++){out+=line(pt(s*30,246),pt(s*30,282),'#c6cdbf');out+=text(s*30+15,261,glyphSigns[s],23,'#8a8068');}
 const cusps=c?c.cusps:Array.from({length:12},(_,i)=>i*30);cusps.forEach((l,i)=>{out+=line(pt(l,172),pt(l,246),i%3===0?'#8a9a91':'#d0d7c9',i%3===0?1.3:.8);out+=text(l+H.mod(cusps[(i+1)%12]-l)/2,214,i+1,12);});
 if(c){for(const a of c.pairs)out+=line(pt(c.planets[a.i].lon,170),pt(c.planets[a.j].lon,170),[60,120].includes(a.angle)?'#78a19b':a.angle===0?'#b69b71':'#bc8d7c',.9,`opacity=".65" ${a.applying?'':'stroke-dasharray="4 4"'}`);
 const placed=[];for(const p of c.planets){let r=195;while(placed.some(x=>Math.abs(H.delta(x.l,p.lon))<11&&Math.abs(x.r-r)<22))r-=24;placed.push({l:p.lon,r});out+=line(pt(p.lon,231),pt(p.lon,244),'#a17e49',2);out+=text(p.lon,r,p.glyph,24,'#172c35');out+=text(p.lon,r-16,`${(p.lon%30).toFixed(0)}°${p.retro?' R':''}`,9,'#9e7740');}
 out+=text(c.asc,310,'ASC',11,'#a17e49');out+=text(c.mc,310,'MC',11,'#a17e49');
 }else{out+='<circle cx="320" cy="320" r="96" fill="#f6f3e9"/><text x="320" y="312" text-anchor="middle" fill="#9a8159" font-family="Georgia,serif" font-size="40">✳</text><text x="320" y="346" text-anchor="middle" fill="#8a9487" font-family="sans-serif" font-size="10" letter-spacing="3">КАРТА МОМЕНТА</text>';}
 $('wheel').innerHTML=`<svg viewBox="0 0 640 640" role="img" aria-label="${c?'Хорарная карта; все значения доступны в таблицах ниже':'Декоративная схема зодиака без положений планет'}">${out}</svg>`;}
function render(c){current=c;const p=c.planets;wheel(c);$('chart-title').textContent='Карта вашего вопроса';$('chart-badge').textContent=c.input.system==='regio'?'РЕГИОМОНТАН':c.input.system==='equal'?'РАВНОДОМНАЯ':'ЦЕЛЬНОЗНАКОВАЯ';$('chart-caption').textContent=`${localTime(c.date,c.input.offset)} · ${c.input.lat.toFixed(4)}°, ${c.input.lon.toFixed(4)}°`;
 $('reading').innerHTML=`<div class="reading-main"><p class="eyebrow">СИМВОЛИЧЕСКАЯ ТРАКТОВКА</p><h3>${escape(c.verdict)}</h3><p>${escape(c.explanation)}</p></div><div class="significators"><div class="panel"><p class="eyebrow">ВЫ · I ДОМ</p><strong>${p[c.querent].glyph} ${p[c.querent].name}</strong><p>${formatLon(p[c.querent].lon)} · ${p[c.querent].house} дом<br>${p[c.querent].dignity.join(', ')}</p></div><div class="panel"><p class="eyebrow">ПРЕДМЕТ · ${c.input.target} ДОМ</p><strong>${p[c.subject].glyph} ${p[c.subject].name}</strong><p>${formatLon(p[c.subject].lon)} · ${p[c.subject].house} дом<br>${p[c.subject].dignity.join(', ')}</p></div></div><div class="notice"><strong>Рецепции</strong><br>${c.receptions.length?c.receptions.map(escape).join('<br>'):'Рецепций по обители и экзальтации между этими управителями нет.'}</div>${c.notices.map(n=>`<div class="notice">${escape(n)}</div>`).join('')}`;
 $('planet-table').innerHTML=p.map(x=>`<tr><td>${x.glyph} ${x.name}${x.retro?' ℞':''}</td><td>${formatLon(x.lon)}</td><td>${x.house}</td><td>${x.dignity.join(', ')}</td></tr>`).join('');
 $('aspect-list').innerHTML=c.pairs.length?c.pairs.map(a=>`<div class="aspect"><span>${p[a.i].name} — ${p[a.j].name}<small>${a.name} · ${a.orb.toFixed(2)}°</small></span><b>${a.applying?'Сходится ↘':'Расходится ↗'}</b></div>`).join(''):'<p class="hint">Мажорных аспектов в выбранных орбисах нет.</p>';
 $('cusps').innerHTML=c.cusps.map((l,i)=>`<div><strong>${i+1}</strong> · ${formatLon(l)}</div>`).join('');$('results').hidden=false;notify('status','');$('moon-list').textContent='Вычисляем точные аспекты…';
 setTimeout(()=>{if(current!==c)return;try{c.lunar=H.lunarEvents(c);$('moon-list').innerHTML=(c.lunar.void?'<div class="notice">Луна без курса по принятому здесь определению. Это не самостоятельный ответ на вопрос.</div>':c.lunar.events.map(e=>`<div class="aspect"><span>Луна — ${H.names[e.i]}<small>${e.name}</small></span><b>${localTime(e.utc,c.input.offset)}</b></div>`).join(''))+`<p class="hint">Выход из знака: ${localTime(c.lunar.ingress,c.input.offset)}</p>`;}catch{$('moon-list').textContent='Не удалось вычислить будущие аспекты Луны.';}},30);}
$('chart-form').onsubmit=e=>{e.preventDefault();notify('error','');try{currentId=null;render(H.calculate(input()));if(innerWidth<721)$('wheel').scrollIntoView({behavior:'smooth',block:'center'});}catch(e){notify('error',e.message);}};
$('save').onclick=()=>{if(!current)return;let entries=readEntries();if(!currentId){const existing=entries.find(e=>JSON.stringify(e.input)===JSON.stringify(current.input));currentId=existing?.id||crypto.randomUUID();}const old=entries.find(e=>e.id===currentId);const entry={id:currentId,input:current.input,outcome:old?.outcome||'',created:old?.created||new Date().toISOString()};if(old)entries=entries.map(e=>e.id===currentId?entry:e);else entries.unshift(entry);if(writeEntries(entries))notify('status','Карта сохранена. Фактический исход можно записать в журнале.');};
function download(name,text,type='text/plain'){if(window.Android?.share){window.Android.share(name,text,type);return;}const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function report(c){return `ХОРАР · 1.0\n${c.input.question}\n${localTime(c.date,c.input.offset)}\nКоординаты: ${c.input.lat}, ${c.input.lon}; дома: ${c.input.system}\n\n${c.verdict}\n${c.explanation}\n\nВы: ${H.names[c.querent]}; предмет: ${H.names[c.subject]}\n${c.receptions.join('\n')}\n${c.notices.join('\n')}\n\nПЛАНЕТЫ\n${c.planets.map(p=>`${p.name}: ${formatLon(p.lon)}, дом ${p.house}, ${p.retro?'ретроградная':'прямая'}; ${p.dignity.join(', ')}`).join('\n')}\n\nАСПЕКТЫ\n${c.pairs.map(a=>`${H.names[a.i]} — ${H.names[a.j]}: ${a.name}, ${a.orb.toFixed(2)}°, ${a.applying?'сходится':'расходится'}`).join('\n')}\n\nКУСПИДЫ\n${c.cusps.map((l,i)=>`${i+1}: ${formatLon(l)}`).join('\n')}\n\nЛУНА\n${c.lunar?c.lunar.events.map(e=>`${e.name} — ${H.names[e.i]}: ${localTime(e.utc,c.input.offset)}`).join('\n'):'Расчёт ещё не завершён'}\n\nАстрологическая интерпретация не является научно подтверждённым прогнозом. Схождение аспекта не гарантирует его совершенствования. Триплицитеты, термы, фасы, передача/собирание света, запрет и рефранация не включены в итоговое суждение версии 1.0.\n`;}
$('export').onclick=()=>current&&download('horar-reading.txt',report(current));
function renderJournal(){const entries=readEntries();$('count').textContent=entries.length;$('entries').innerHTML=entries.length?entries.map(e=>`<article class="panel entry"><h3>${escape(e.input.question)}</h3><div class="entry-meta">${escape(localTime(e.input.utc,e.input.offset))} · ${escape(e.input.lat)}, ${escape(e.input.lon)}</div><div class="actions"><button class="secondary" data-open="${escape(e.id)}">Открыть карту ↗</button><button class="text-button danger" data-delete="${escape(e.id)}">Удалить</button></div><label for="outcome-${escape(e.id)}">Что произошло на самом деле?</label><textarea id="outcome-${escape(e.id)}" data-outcome="${escape(e.id)}" rows="2" maxlength="3000" placeholder="Запишите исход, когда он станет известен">${escape(e.outcome||'')}</textarea><button class="secondary" data-note="${escape(e.id)}">Сохранить исход</button></article>`).join(''):'<div class="empty"><h2>Пока ни одной карты</h2><p>Постройте карту и нажмите «Сохранить в журнал».</p><button class="secondary" id="first-chart">Задать вопрос ↗</button></div>';
 if($('first-chart'))$('first-chart').onclick=()=>page('workspace');
 document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const e=entries.find(e=>e.id===b.dataset.open);if(!e)return;try{for(const id of ['question','offset','lat','lon','system','target','city'])$(id).value=e.input[id];$('moment').value=e.input.local||new Date(+new Date(e.input.utc)+e.input.offset*3600000).toISOString().slice(0,16);currentId=e.id;render(H.calculate(e.input));page('workspace');}catch(err){notify('journal-status',err.message);}});
 document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{const next=readEntries().map(e=>e.id===b.dataset.note?{...e,outcome:document.getElementById('outcome-'+e.id).value}:e);if(writeEntries(next))notify('journal-status','Исход сохранён.');});
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Удалить эту карту из журнала?'))return;const deleted=readEntries().find(e=>e.id===b.dataset.delete);if(writeEntries(readEntries().filter(e=>e.id!==b.dataset.delete))){renderJournal();notify('journal-status','Карта удалена.');const undo=document.createElement('button');undo.className='text-button';undo.textContent='Отменить удаление';undo.onclick=()=>{if(!readEntries().some(e=>e.id===deleted.id)&&writeEntries([deleted,...readEntries()])){renderJournal();notify('journal-status','Карта восстановлена.');}};$('journal-status').append(' ',undo);}});}
$('backup').onclick=()=>download('horar-journal.json',JSON.stringify({format:'horar-journal',version:1,entries:readEntries()},null,2),'application/json');
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('Файл больше 5 МБ.');const data=JSON.parse(await f.text());if(data.format!=='horar-journal'||data.version!==1||!Array.isArray(data.entries)||data.entries.length>500)throw Error('Нужен экспорт журнала Хорар 1.0 (до 500 записей).');const clean=data.entries.map(e=>{if(!e.input||!Number.isFinite(e.input.offset)||e.input.offset< -12||e.input.offset>14||typeof e.outcome!=='string'||e.outcome.length>3000)throw Error('Некорректные данные записи.');H.calculate(e.input);return {id:typeof e.id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(e.id)?e.id:crypto.randomUUID(),input:e.input,outcome:e.outcome,created:e.created};});const existing=readEntries(),ids=new Set(existing.map(e=>e.id)),add=clean.filter(e=>{if(ids.has(e.id))return false;ids.add(e.id);return true;});if(writeEntries([...add,...existing])){renderJournal();notify('journal-status',`Добавлено карт: ${add.length}. Существующие записи сохранены.`);}}catch(err){notify('journal-status','Импорт не выполнен: '+err.message);}finally{e.target.value='';}};
now();wheel(null);$('count').textContent=readEntries().length;
if('serviceWorker' in navigator&&location.hostname!=='app.local')navigator.serviceWorker.register('./sw.js').catch(()=>{});
